// Bundles the desktop's SQLite migrations (src-tauri/migrations/*.sql) for the phone app, which
// runs the same files in order (PLAN D229). Run after adding a migration; src/shared.test.ts fails
// when the generated file is out of date.
import { readdirSync, readFileSync, writeFileSync } from "node:fs";

const DIR = "src-tauri/migrations";
export const OUT = "mobile/src/db/migrations.ts";

export function render() {
  const files = readdirSync(DIR).filter((f) => /^\d{4}_.*\.sql$/.test(f)).sort();
  const items = files.map((f) => `  { version: ${Number(f.slice(0, 4))}, sql: ${JSON.stringify(readFileSync(`${DIR}/${f}`, "utf8"))} },`);
  return `// Generated by scripts/mobile-migrations.mjs from ${DIR}. Do not edit.\nexport const MIGRATIONS: { version: number; sql: string }[] = [\n${items.join("\n")}\n];\n`;
}

if (process.argv[1]?.endsWith("mobile-migrations.mjs")) {
  writeFileSync(OUT, render());
  console.log(`Wrote ${OUT}`);
}
